import java.util.*;
import java.util.concurrent.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

/** 加载实际V006；账号、会话、租约、事务及唯一约束真实运行于H2，模型只使用本地替身。 */
class MessageFeedbackTest {
    ChatBoundaryTest fixture;JdbcTemplate db;ChatService chat;
    record Answer(String conversation,String message,String generation){}
    @BeforeEach void setup()throws Exception{fixture=new ChatBoundaryTest();fixture.prepare();db=fixture.db;chat=fixture.chat;}
    Answer answer(boolean linked){String conversation=chat.createConversation(2,"已有回答").get("id").toString();return answerIn(conversation,linked);}
    Answer answerIn(String conversation,boolean linked){String message=UUID.randomUUID().toString(),generation=UUID.randomUUID().toString();LocalDateTime now=LocalDateTime.now().minusSeconds(10);
        db.update("INSERT INTO ps_chat_message(id,conversation_id,generation_id,role,content,references_json,state,created_at) VALUES(?,?,?,'assistant','已存回答原文','[]','COMPLETE',?)",message,conversation,linked?generation:null,now);
        db.update("INSERT INTO ps_chat_generation(id,conversation_id,user_id,assistant_message_id,client_request_id,state,request_json,created_at,updated_at) VALUES(?,?,2,?,?,'COMPLETE','{\"text\":\"原问题\"}',?,?)",generation,conversation,message,UUID.randomUUID().toString(),now,now);return new Answer(conversation,message,generation);
    }
    Map<String,Object> body(Answer answer,String rating,String reason){return new LinkedHashMap<>(Map.of("messageId",answer.message(),"rating",rating,"reason",reason));}
    Map<String,Object> send(Answer answer){return chat.submit(2,Map.of("conversationId",answer.conversation(),"text","反馈：回答有帮助","clientRequestId","feedback-request"));}
    long count(String table){return db.queryForObject("SELECT COUNT(*) FROM "+table,Long.class);}
    Map<String,Object> listed(Answer answer){return ((List<Map<String,Object>>)chat.messages(2,answer.conversation(),1,100).get("rows")).stream().filter(m->answer.message().equals(m.get("id"))).findFirst().orElseThrow();}
    void handlers(){@SuppressWarnings("unchecked") var handlers=(org.springframework.beans.factory.ObjectProvider<com.ruoyi.paismart.application.jobs.PaismartJobHandler>)mock(org.springframework.beans.factory.ObjectProvider.class);when(handlers.orderedStream()).thenAnswer(i->java.util.stream.Stream.of(chat));fixture.jobs.handlers(handlers);}

    @Test void currentValueOnlyChangesForRatingOrReasonAndWritesSafeAudit(){
        Answer a=answer(true);Map<String,Object> first=chat.feedback(2,body(a,"good","个人理由-原文不得进入审计"),"first");assertEquals(a.message(),first.get("messageId"));assertEquals(a.generation(),first.get("generationId"));assertEquals(a.conversation(),first.get("conversationId"));assertEquals(1L,first.get("rowVersion"));assertEquals(true,first.get("changed"));
        var unchanged=chat.feedback(2,body(a,"GOOD","个人理由-原文不得进入审计"),"same-value");assertEquals(false,unchanged.get("changed"));assertEquals(1L,unchanged.get("rowVersion"));
        var changed=chat.feedback(2,body(a,"BAD","个人理由-原文不得进入审计"),"rating-change");assertEquals(2L,changed.get("rowVersion"));var changedReason=chat.feedback(2,body(a,"BAD","理由已变化"),"reason-change");assertEquals(3L,changedReason.get("rowVersion"));
        assertEquals(1,count("ps_tool_feedback"));assertEquals(3,count("ps_audit_event"));assertEquals(4,count("ps_mutation_request"));var row=listed(a);assertEquals("BAD",row.get("rating"));assertEquals(3L,row.get("feedbackVersion"));assertEquals(true,row.get("feedbackEligible"));
        String audit=db.queryForList("SELECT reason FROM ps_audit_event",String.class).toString();assertFalse(audit.contains("个人理由"));assertFalse(audit.contains("理由已变化"));assertFalse(audit.contains("已存回答原文"));assertTrue(audit.contains("reasonHash"));assertTrue(audit.contains(a.generation()));
    }
    @Test void sameKeyReplaysOriginalReceiptAfterLaterChangeAndRejectsChangedInput(){Answer a=answer(true);var original=chat.feedback(2,body(a,"GOOD","首次"),"same");chat.feedback(2,body(a,"BAD","修改"),"later");assertEquals(original,chat.feedback(2,body(a,"good","首次"),"same"));assertThrows(IllegalStateException.class,()->chat.feedback(2,body(a,"GOOD","不同理由"),"same"));var differentVersion=body(a,"GOOD","首次");differentVersion.put("expectedVersion",0);assertThrows(IllegalStateException.class,()->chat.feedback(2,differentVersion,"same"));assertEquals("BAD",listed(a).get("rating"));assertEquals(2,count("ps_audit_event"));}
    @Test void suppliedVersionMustMatchEvenForUnchangedFeedbackAndMustBeExact(){Answer a=answer(true);var first=body(a,"GOOD","理由");first.put("expectedVersion",0);chat.feedback(2,first,"first");assertThrows(IllegalStateException.class,()->chat.feedback(2,first,"stale"));var next=body(a,"BAD","理由");next.put("expectedVersion",1);assertEquals(2L,chat.feedback(2,next,"next").get("rowVersion"));next.put("expectedVersion",1.5);assertThrows(IllegalArgumentException.class,()->chat.feedback(2,next,"fractional"));next.put("expectedVersion",null);assertThrows(IllegalArgumentException.class,()->chat.feedback(2,next,"null"));assertEquals(2,count("ps_mutation_request"));}
    @Test void invalidKeyOrForeignOwnerNeverWrites(){Answer a=answer(true);assertThrows(IllegalArgumentException.class,()->chat.feedback(2,body(a,"GOOD",""),null));assertThrows(IllegalArgumentException.class,()->chat.feedback(2,body(a,"GOOD","")," "));assertThrows(IllegalArgumentException.class,()->chat.feedback(3,body(a,"GOOD",""),"foreign"));assertEquals(0,count("ps_tool_feedback"));assertEquals(0,count("ps_audit_event"));assertEquals(0,count("ps_mutation_request"));}
    @Test void auditMessagesAreReadOnlyEvenForAdministratorAndDoNotExpandWriteOwnership(){Answer a=answer(true);chat.feedback(2,body(a,"GOOD","本人评价"),"owner");var audit=chat.auditMessages(new SpaceService.Scope(1,true),a.conversation(),1,20);Map<String,Object> row=Values.map(Values.list(audit.get("rows")).get(0));assertEquals(false,row.get("feedbackEligible"));assertEquals("GOOD",row.get("rating"));assertEquals(false,Values.map(Values.list(chat.auditMessages(new SpaceService.Scope(2,false),a.conversation(),1,20).get("rows")).get(0)).get("feedbackEligible"));assertEquals(true,listed(a).get("feedbackEligible"));assertThrows(IllegalArgumentException.class,()->chat.feedback(1,body(a,"BAD","管理员不能代评"),"admin"));assertEquals(1,count("ps_tool_feedback"));assertEquals(1,count("ps_audit_event"));}
    @ParameterizedTest @CsvSource({"assistant,QUEUED,回答","assistant,RUNNING,回答","assistant,INTERRUPTED,回答","user,COMPLETE,回答","assistant,COMPLETE,''"})
    void onlyNonemptyTerminalAssistantMessagesAreEligible(String role,String state,String content){Answer a=answer(true);db.update("UPDATE ps_chat_message SET role=?,state=?,content=? WHERE id=?",role,state,content,a.message());assertEquals(false,listed(a).get("feedbackEligible"));assertNull(listed(a).get("rating"));assertEquals(0L,listed(a).get("feedbackVersion"));assertThrows(IllegalArgumentException.class,()->chat.feedback(2,body(a,"GOOD",""),"invalid"));assertEquals(0,count("ps_tool_feedback"));}
    @ParameterizedTest @CsvSource({"COMPLETE","STOPPED","FAILED"}) void actualContentInEachPermittedTerminalStateCanBeRated(String state){Answer a=answer(true);db.update("UPDATE ps_chat_message SET state=? WHERE id=?",state,a.message());assertEquals(1L,chat.feedback(2,body(a,"GOOD",""),state).get("rowVersion"));}
    @Test void exactLegacyPointerWorksWithoutGuessingOrRewritingUnknownFeedback(){Answer a=answer(false);db.update("INSERT INTO ps_tool_feedback(id,user_id,conversation_id,rating,note,created_at) VALUES('legacy',2,?,'BAD','未知历史',CURRENT_TIMESTAMP)",a.conversation());assertEquals(a.generation(),listed(a).get("generationId"));chat.feedback(2,body(a,"GOOD","当前"),"current");assertEquals(2,count("ps_tool_feedback"));assertNull(db.queryForObject("SELECT generation_id FROM ps_chat_message WHERE id=?",String.class,a.message()));assertNull(db.queryForObject("SELECT message_id FROM ps_tool_feedback WHERE id='legacy'",String.class));assertEquals("GOOD",listed(a).get("rating"));}
    @Test void ambiguousOrForeignGenerationCannotBeGuessed(){Answer a=answer(false);db.update("INSERT INTO ps_chat_generation(id,conversation_id,user_id,assistant_message_id,client_request_id,state,request_json,created_at,updated_at) VALUES('foreign-generation',?,3,?,'foreign','COMPLETE','{}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)",a.conversation(),a.message());assertEquals(false,listed(a).get("feedbackEligible"));assertThrows(IllegalArgumentException.class,()->chat.feedback(2,body(a,"GOOD",""),"ambiguous"));db.update("UPDATE ps_chat_message SET generation_id='foreign-generation' WHERE id=?",a.message());assertEquals(false,listed(a).get("feedbackEligible"));assertEquals(0,count("ps_tool_feedback"));}
    @Test void inconsistentExistingFeedbackIsNotExposedOrOverwritten(){Answer a=answer(true);db.update("INSERT INTO ps_tool_feedback(id,user_id,conversation_id,message_id,generation_id,rating,note,created_at) VALUES('inconsistent',2,?,?,'other-generation','BAD','旧关联',CURRENT_TIMESTAMP)",a.conversation(),a.message());assertNull(listed(a).get("rating"));assertEquals(0L,listed(a).get("feedbackVersion"));assertThrows(IllegalStateException.class,()->chat.feedback(2,body(a,"GOOD",""),"correct"));assertEquals("other-generation",db.queryForObject("SELECT generation_id FROM ps_tool_feedback",String.class));assertEquals(0,count("ps_audit_event"));}
    @Test void auditFailureRollsBackCurrentValueAndIdempotencyReceipt(){Answer a=answer(true);db.execute("ALTER TABLE ps_audit_event ADD CONSTRAINT reject_feedback CHECK (action<>'CHAT_FEEDBACK')");assertThrows(org.springframework.dao.DataIntegrityViolationException.class,()->chat.feedback(2,body(a,"GOOD","理由"),"atomic"));assertEquals(0,count("ps_tool_feedback"));assertEquals(0,count("ps_mutation_request"));db.execute("ALTER TABLE ps_audit_event DROP CONSTRAINT reject_feedback");assertEquals(1L,chat.feedback(2,body(a,"GOOD","理由"),"atomic").get("rowVersion"));}
    @Test void concurrentSameKeySerializesToOneValueAuditAndReceipt()throws Exception{Answer a=answer(true);var pool=Executors.newFixedThreadPool(2);var start=new CountDownLatch(1);try{Callable<Map<String,Object>> work=()->{start.await();return chat.feedback(2,body(a,"GOOD","并发"),"concurrent");};var first=pool.submit(work);var second=pool.submit(work);start.countDown();assertEquals(first.get(15,TimeUnit.SECONDS),second.get(15,TimeUnit.SECONDS));assertEquals(1,count("ps_tool_feedback"));assertEquals(1,count("ps_audit_event"));assertEquals(1,count("ps_mutation_request"));}finally{pool.shutdownNow();}}
    @Test void concurrentFirstVersionsAllowOnlyOneWinner()throws Exception{Answer a=answer(true);var pool=Executors.newFixedThreadPool(2);var start=new CountDownLatch(1);try{List<Future<Boolean>> futures=new ArrayList<>();for(String rating:List.of("GOOD","BAD"))futures.add(pool.submit(()->{start.await();var request=body(a,rating,"");request.put("expectedVersion",0);try{chat.feedback(2,request,rating);return true;}catch(IllegalStateException stale){return false;}}));start.countDown();int winners=0;for(var future:futures)if(future.get(15,TimeUnit.SECONDS))winners++;assertEquals(1,winners);assertEquals(1,count("ps_tool_feedback"));assertEquals(1,count("ps_audit_event"));assertEquals(1,count("ps_mutation_request"));}finally{pool.shutdownNow();}}

    @Test void toolFreezesExistingAnswerAndDoesNotFollowLaterAnswersOrItsOwnText(){Answer a=answer(true);var run=send(a);var later=answerIn(a.conversation(),true);db.update("UPDATE ps_chat_message SET created_at=DATEADD('SECOND',10,CURRENT_TIMESTAMP) WHERE id=?",later.message());fixture.turns(Map.of("content","本轮新增文字","tool_calls",List.of(fixture.tool("one","submit_feedback",Map.of("rating","GOOD","reason","明确理由")))),fixture.plan(fixture.tool("two","submit_feedback",Map.of("rating","GOOD","reason","明确理由"))),Map.of("content","完成"));chat.processJob(fixture.claim());assertEquals(a.message(),db.queryForObject("SELECT message_id FROM ps_tool_feedback",String.class));assertEquals(a.generation(),db.queryForObject("SELECT generation_id FROM ps_tool_feedback",String.class));assertEquals(1,count("ps_audit_event"));assertEquals(1,count("ps_mutation_request"));assertNotEquals(run.get("messageId"),a.message());}
    @Test void latestUnassociatedAnswerBlocksGuessingAnEarlierValidTarget(){Answer a=answer(true);db.update("INSERT INTO ps_chat_message(id,conversation_id,role,content,state,created_at) VALUES('unknown-latest',?,'assistant','无可靠关联的最新答案','COMPLETE',CURRENT_TIMESTAMP)",a.conversation());var run=send(a);var request=Jsons.map(db.queryForObject("SELECT request_json FROM ps_chat_generation WHERE id=?",String.class,run.get("generationId")));assertFalse(request.containsKey("_feedbackTarget"));fixture.turns(fixture.plan(fixture.tool("one","submit_feedback",Map.of("rating","GOOD"))),Map.of("content","未记录"));chat.processJob(fixture.claim());assertEquals(0,count("ps_tool_feedback"));}
    @Test void noPreviousAnswerDoesNotAuthorizeRatingThisRunsNewAnswer(){var run=fixture.send("反馈：回答有帮助");fixture.turns(Map.of("content","新生成内容","tool_calls",List.of(fixture.tool("one","submit_feedback",Map.of("rating","GOOD")))),Map.of("content","未记录"));chat.processJob(fixture.claim());assertEquals(0,count("ps_tool_feedback"));assertFalse(Jsons.map(db.queryForObject("SELECT request_json FROM ps_chat_generation WHERE id=?",String.class,run.get("generationId"))).containsKey("_feedbackTarget"));}
    @Test void clientAndModelCannotSupplyFeedbackAssociations(){Answer a=answer(true);assertThrows(IllegalArgumentException.class,()->chat.submit(2,Map.of("text","反馈：回答有帮助","clientRequestId","forged","_feedbackTarget",Map.of("messageId",a.message()))));send(a);fixture.turns(fixture.plan(fixture.tool("one","submit_feedback",Map.of("rating","GOOD","messageId",a.message()))),Map.of("content","未记录"));chat.processJob(fixture.claim());assertEquals(0,count("ps_tool_feedback"));}
    @Test void stopFlagWithLiveJobLeaseBlocksFeedbackReturnedByModel(){Answer a=answer(true);var run=send(a);var job=fixture.claim();doAnswer(i->{chat.stop(2,run.get("generationId").toString());fixture.jobs.requireLease(job.id(),job.leaseToken());return fixture.plan(fixture.tool("one","submit_feedback",Map.of("rating","GOOD")));}).when(fixture.models).streamTurn(anyLong(),anyString(),anyList(),anyList(),any(),any(),any());assertEquals("STOPPED",chat.processJob(job).get("state"));assertEquals(0,count("ps_tool_feedback"));assertEquals(0,count("ps_audit_event"));assertEquals(0,count("ps_mutation_request"));}
    @SuppressWarnings("unchecked") void directTool(Map<String,Object> run,JobService.Job job){var execution=(ThreadLocal<JobService.Job>)ReflectionTestUtils.getField(chat,"execution");execution.set(job);try{ReflectionTestUtils.invokeMethod(chat,"executeTool",2L,new SpaceService.Scope(2,false),run.get("conversationId"),run.get("generationId"),"submit_feedback",Map.of("rating","GOOD"),"one","不得信任此参数",new ArrayList<Map<String,Object>>(),new LinkedHashMap<String,Integer>(),new LinkedHashMap<Integer,String>(),run.get("messageId"),null,new StringBuilder());}finally{execution.remove();}}
    @Test void terminalExecutingGenerationCannotWriteToolFeedbackDespiteLiveLease(){Answer a=answer(true);var run=send(a);var job=fixture.claim();db.update("UPDATE ps_chat_generation SET state='FAILED' WHERE id=?",run.get("generationId"));fixture.jobs.requireLease(job.id(),job.leaseToken());assertThrows(IllegalStateException.class,()->directTool(run,job));assertEquals(0,count("ps_tool_feedback"));assertEquals(0,count("ps_mutation_request"));}
    @Test void revokedJobLeaseCannotWriteToolFeedback(){Answer a=answer(true);var run=send(a);var job=fixture.claim();db.update("UPDATE ps_chat_generation SET state='RUNNING' WHERE id=?",run.get("generationId"));fixture.jobs.cancel(job.id(),job.rowVersion());assertThrows(IllegalStateException.class,()->directTool(run,job));assertEquals(0,count("ps_tool_feedback"));}
    @Test void retryKeepsFrozenTargetAndBothMessagesBoundWithoutRepeatingFeedback(){Answer a=answer(true);var run=send(a);handlers();java.util.concurrent.atomic.AtomicInteger turn=new java.util.concurrent.atomic.AtomicInteger();doAnswer(i->{if(turn.getAndIncrement()==0)return fixture.plan(fixture.tool("first-call","submit_feedback",Map.of("rating","GOOD","reason","固定理由")));throw new IllegalStateException("回答流中断");}).when(fixture.models).streamTurn(anyLong(),anyString(),anyList(),anyList(),any(),any(),any());var job=fixture.claim();assertThrows(IllegalStateException.class,()->chat.processJob(job));String frozen=db.queryForObject("SELECT request_json FROM ps_chat_generation WHERE id=?",String.class,run.get("generationId"));db.update("UPDATE ps_job SET retries=3 WHERE id=?",job.id());fixture.jobs.fail(job.id(),job.leaseToken(),"回答中断");fixture.jobs.retry(job.id(),fixture.jobs.get(job.id()).rowVersion());var restarted=chat.generation(2,run.get("generationId").toString());assertNotEquals(run.get("messageId"),restarted.get("messageId"));assertEquals(run.get("generationId"),db.queryForObject("SELECT generation_id FROM ps_chat_message WHERE id=?",String.class,run.get("messageId")));assertEquals(run.get("generationId"),db.queryForObject("SELECT generation_id FROM ps_chat_message WHERE id=?",String.class,restarted.get("messageId")));assertEquals(frozen,db.queryForObject("SELECT request_json FROM ps_chat_generation WHERE id=?",String.class,run.get("generationId")));fixture.turns(fixture.plan(fixture.tool("different-model-call-id","submit_feedback",Map.of("rating","GOOD","reason","固定理由"))),Map.of("content","已恢复"));chat.processJob(fixture.jobs.claimById(job.id(),180).orElseThrow());assertEquals(a.message(),db.queryForObject("SELECT message_id FROM ps_tool_feedback",String.class));assertEquals(1,count("ps_audit_event"));assertEquals(1,count("ps_mutation_request"));}
    @Test void submitAndRetryCannotQueueTwoGenerationsForOneUser()throws Exception{
        Answer a=answer(true);var old=send(a);handlers();var job=fixture.claim();
        db.update("UPDATE ps_job SET retries=3 WHERE id=?",job.id());fixture.jobs.fail(job.id(),job.leaseToken(),"可重试失败");
        long version=fixture.jobs.get(job.id()).rowVersion();
        var providerService=(ProviderService)ReflectionTestUtils.getField(chat,"providers");
        var provider=providerService.active("LLM");
        var submitAtProvider=new CountDownLatch(1);var releaseSubmit=new CountDownLatch(1);var retryEntered=new CountDownLatch(1);
        doAnswer(i->{submitAtProvider.countDown();if(!releaseSubmit.await(10,TimeUnit.SECONDS))throw new IllegalStateException("夹具提交等待超时");return provider;}).when(providerService).active("LLM");
        com.ruoyi.paismart.application.jobs.PaismartJobHandler observed=new com.ruoyi.paismart.application.jobs.PaismartJobHandler(){
            public boolean supports(String type){return chat.supports(type);}
            public Map<String,Object> processJob(JobService.Job input){return chat.processJob(input);}
            public void onRetry(JobService.Job input){retryEntered.countDown();chat.onRetry(input);}
        };
        @SuppressWarnings("unchecked") var handlerProvider=(org.springframework.beans.factory.ObjectProvider<com.ruoyi.paismart.application.jobs.PaismartJobHandler>)mock(org.springframework.beans.factory.ObjectProvider.class);
        when(handlerProvider.orderedStream()).thenAnswer(i->java.util.stream.Stream.of(observed));fixture.jobs.handlers(handlerProvider);
        var pool=Executors.newFixedThreadPool(2);
        try{
            var submitted=pool.submit(()->chat.submit(2,Map.of("conversationId",a.conversation(),"text","新提问","clientRequestId","concurrent-submit")));
            assertTrue(submitAtProvider.await(10,TimeUnit.SECONDS));
            var retried=pool.submit(()->{try{fixture.jobs.retry(job.id(),version);return true;}catch(IllegalStateException busy){assertTrue(busy.getMessage().contains("JOB_BUSY"));return false;}});
            assertTrue(retryEntered.await(10,TimeUnit.SECONDS));
            // 提交已通过无活跃任务检查但尚未写生成；旧实现此时会先完成重试。
            try{retried.get(1,TimeUnit.SECONDS);}catch(TimeoutException waitingForUserLock){/* 新实现等待提交释放用户锁。 */}
            releaseSubmit.countDown();assertNotNull(submitted.get(10,TimeUnit.SECONDS));
            boolean retrySucceeded=retried.get(10,TimeUnit.SECONDS);
            assertEquals(1,chat.active(2).size());assertFalse(retrySucceeded);assertEquals("FAILED",chat.generation(2,old.get("generationId").toString()).get("state"));
            assertEquals("FAILED",fixture.jobs.get(job.id()).state());
        }finally{releaseSubmit.countDown();pool.shutdownNow();}
    }
    @Test void retryPreservesExactLegacyAnswerBeforeMovingItsPointer(){Answer a=answer(false);db.update("UPDATE ps_chat_generation SET state='STOPPED' WHERE id=?",a.generation());var job=new JobService.Job("legacy-job",2,null,"CHAT_GENERATE","QUEUED",Map.of("generationId",a.generation()),Map.of(),null,null,0,null,1);chat.onRetry(job);assertEquals(a.generation(),db.queryForObject("SELECT generation_id FROM ps_chat_message WHERE id=?",String.class,a.message()));assertNotEquals(a.message(),chat.generation(2,a.generation()).get("messageId"));assertEquals(true,listed(a).get("feedbackEligible"));chat.feedback(2,body(a,"GOOD","旧内容"),"old-after-retry");assertEquals(a.generation(),listed(a).get("generationId"));}
    @Test void retryRejectsAmbiguousLegacyPointerWithoutChangingEitherMessage(){Answer a=answer(false);db.update("UPDATE ps_chat_generation SET state='STOPPED' WHERE id=?",a.generation());db.update("INSERT INTO ps_chat_generation(id,conversation_id,user_id,assistant_message_id,client_request_id,state,request_json,created_at,updated_at) VALUES('duplicate',?,3,?,'duplicate','STOPPED','{}',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)",a.conversation(),a.message());var job=new JobService.Job("legacy-job",2,null,"CHAT_GENERATE","QUEUED",Map.of("generationId",a.generation()),Map.of(),null,null,0,null,1);assertThrows(IllegalStateException.class,()->chat.onRetry(job));assertNull(db.queryForObject("SELECT generation_id FROM ps_chat_message WHERE id=?",String.class,a.message()));assertEquals(a.message(),chat.generation(2,a.generation()).get("messageId"));assertEquals(1,count("ps_chat_message"));}
    @Test void retryRejectsConflictingReliableGenerationWithoutOverwritingIt(){Answer a=answer(true);db.update("UPDATE ps_chat_generation SET state='STOPPED' WHERE id=?",a.generation());db.update("UPDATE ps_chat_message SET generation_id='another-generation' WHERE id=?",a.message());var job=new JobService.Job("legacy-job",2,null,"CHAT_GENERATE","QUEUED",Map.of("generationId",a.generation()),Map.of(),null,null,0,null,1);assertThrows(IllegalStateException.class,()->chat.onRetry(job));assertEquals("another-generation",db.queryForObject("SELECT generation_id FROM ps_chat_message WHERE id=?",String.class,a.message()));assertEquals(1,count("ps_chat_message"));}
    @Test void modelContextOnlyContainsLegallyBoundCurrentFeedback(){Answer a=answer(true);chat.feedback(2,body(a,"GOOD","合法当前理由"),"valid");db.update("INSERT INTO ps_tool_feedback(id,user_id,conversation_id,rating,note,created_at) VALUES('unknown-history',2,?,'BAD','未知历史不能进入模型',DATEADD('SECOND',100,CURRENT_TIMESTAMP))",a.conversation());var run=chat.submit(2,Map.of("conversationId",a.conversation(),"text","你好","clientRequestId","context"));fixture.turns(Map.of("content","欢迎"));chat.processJob(fixture.claim());var inputs=org.mockito.ArgumentCaptor.forClass(List.class);verify(fixture.models).streamTurn(anyLong(),anyString(),inputs.capture(),anyList(),any(),any(),any());String system=inputs.getValue().get(0).toString();assertTrue(system.contains("合法当前理由"));assertFalse(system.contains("未知历史不能进入模型"));assertTrue(system.contains(a.message()));assertEquals("COMPLETE",chat.generation(2,run.get("generationId").toString()).get("state"));}
}
